ALTER TABLE public.activity_logs ADD COLUMN file_name text;
CREATE OR REPLACE FUNCTION public.audit_file_registration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.workspace_id IS NOT NULL THEN INSERT INTO public.activity_logs(workspace_id,user_id,file_id,file_name,action) VALUES(NEW.workspace_id,NEW.user_id,NEW.id,NEW.name,'File uploaded'); END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id, left(NEW.raw_user_meta_data->>'display_name',100)) ON CONFLICT(id) DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER memora_create_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
INSERT INTO public.profiles(id) SELECT id FROM auth.users ON CONFLICT(id) DO NOTHING;
CREATE UNIQUE INDEX files_storage_path_unique ON public.files(storage_path);
REVOKE INSERT, UPDATE ON public.files FROM authenticated;
REVOKE INSERT ON public.processing_jobs FROM authenticated;
CREATE OR REPLACE FUNCTION public.register_verified_original(p_user uuid,p_workspace uuid,p_path text,p_name text,p_format text,p_size bigint,p_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=p_workspace AND user_id=p_user) THEN RAISE EXCEPTION 'Workspace access required'; END IF; IF p_path NOT LIKE p_user::text || '/%' OR p_size<=0 OR p_size>52428800 OR p_hash !~ '^[0-9a-f]{64}$' OR p_format NOT IN ('MP4','MOV','PDF','PPTX','DOCX') THEN RAISE EXCEPTION 'Invalid original'; END IF; INSERT INTO public.files(user_id,workspace_id,name,format,size_bytes,storage_path,sha256,status) VALUES(p_user,p_workspace,p_name,p_format,p_size,p_path,p_hash,'Uploaded') ON CONFLICT(storage_path) DO NOTHING RETURNING id INTO f; IF f IS NULL THEN SELECT id INTO f FROM public.files WHERE storage_path=p_path AND user_id=p_user AND workspace_id=p_workspace AND sha256=p_hash AND size_bytes=p_size; END IF; IF f IS NULL THEN RAISE EXCEPTION 'Conflicting registration'; END IF; RETURN f; END $$;
REVOKE ALL ON FUNCTION public.register_verified_original(uuid,uuid,text,text,text,bigint,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.register_verified_original(uuid,uuid,text,text,text,bigint,text) TO service_role;
DROP POLICY originals_workspace_read ON storage.objects;
CREATE POLICY originals_workspace_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='original-files' AND EXISTS(SELECT 1 FROM public.files f WHERE f.storage_path=storage.objects.name AND public.is_workspace_member(f.workspace_id)));
COMMENT ON FUNCTION public.register_verified_original(uuid,uuid,text,text,text,bigint,text) IS 'Only called after authenticated server verification of stored original bytes; registration and upload audit are atomic.';